package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.comparison.*;import static com.aistock.prediction.comparison.ComparisonRecords.*;import static com.aistock.prediction.comparison.ComparisonTestEvidence.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class ComparisonMysqlTest {
 final Instant now=Instant.parse("2026-10-13T00:00:00Z");final Clock clock=Clock.fixed(now,ZoneOffset.UTC);
 List<JsonNode> sources(){return List.of(sample("SH600030",new String[]{"100","110","99"},new String[]{"10","20","30"}),sample("SH600276",new String[]{"10","11","12"},new String[]{"10","20","30"}));}
 Input input(List<JsonNode> e){return new Input(UUID.randomUUID(),List.of("SH600030","SH600276"),LocalDate.parse("2026-07-09"),LocalDate.parse("2026-10-09"),e.stream().map(n->UUID.fromString(n.path("evidenceId").asText())).toList());}
 @Test void ownerReplayImmutableResultAndFailureIsolation(){var db=new ModelDatabaseFixture();var r=new ComparisonRepository(db.jdbc,M);var owner=UUID.randomUUID();var e=sources();var in=input(e);var c=r.claim(owner,in,now);assertTrue(c.execute());assertFalse(r.claim(owner,in,now).execute());var done=r.complete(owner,in,c.generation(),new ComparisonCalculator(clock).calculate(in,e),e,now.plusSeconds(1));assertEquals("SUCCEEDED",done.state());assertEquals(done.comparisonId(),r.replay(owner,in,now).comparisonId());assertThrows(RuntimeException.class,()->r.get(UUID.randomUUID(),done.comparisonId()));assertThrows(RuntimeException.class,()->r.operation(UUID.randomUUID(),in.requestId(),now));assertTrue(r.claim(UUID.randomUUID(),in,now).execute());assertThrows(RuntimeException.class,()->r.replay(owner,new Input(in.requestId(),in.instrumentIds(),in.from().minusMonths(3),in.to(),in.evidenceIds()),now));assertFalse(r.get(owner,done.comparisonId()).has("sourceSnapshots"));assertEquals(1,r.list(owner,null,null).items().size());assertFalse(r.list(owner,null,null).items().get(0).toString().contains("normalizedClose"));}
 @Test void staleWorkerCannotCommitOrOverwriteNewLease(){var db=new ModelDatabaseFixture();var r=new ComparisonRepository(db.jdbc,M);var e=sources();var in=input(e);var u=UUID.randomUUID();var a=r.claim(u,in,now);assertTrue(r.operation(u,in.requestId(),now.plusSeconds(46)).expired());var b=r.claim(u,in,now.plusSeconds(46));assertTrue(b.execute());assertNotEquals(a.generation(),b.generation());assertThrows(RuntimeException.class,()->r.complete(u,in,a.generation(),new ComparisonCalculator(clock).calculate(in,e),e,now.plusSeconds(47)));assertEquals(0,db.jdbc.queryForObject("SELECT COUNT(*) FROM stock_comparison_result",Integer.class));assertThrows(RuntimeException.class,()->r.fail(u,in,a.generation(),"COMPARISON_MARKET_UNAVAILABLE",now.plusSeconds(47)));r.fail(u,in,b.generation(),"COMPARISON_MARKET_UNAVAILABLE",now.plusSeconds(47));assertEquals("FAILED",r.replay(u,in,now.plusSeconds(48)).state());assertFalse(r.claim(u,in,now.plusSeconds(100)).execute());}
 @Test void keysetPagingHasFixedUpperAndStringCursors(){var db=new ModelDatabaseFixture();var r=new ComparisonRepository(db.jdbc,M);db.jdbc.execute("ALTER TABLE stock_comparison_result AUTO_INCREMENT=9007199254740993");var e=sources();var owner=UUID.randomUUID();for(int i=0;i<11;i++){var in=input(e);var c=r.claim(owner,in,now);r.complete(owner,in,c.generation(),new ComparisonCalculator(clock).calculate(in,e),e,now.plusSeconds(1));}var page=r.list(owner,null,null);assertEquals(10,page.items().size());assertTrue(Long.parseLong(page.upper())>9007199254740992L);var extra=input(e);var c=r.claim(owner,extra,now);r.complete(owner,extra,c.generation(),new ComparisonCalculator(clock).calculate(extra,e),e,now.plusSeconds(1));assertEquals(1,r.list(owner,page.nextBefore(),page.upper()).items().size());assertEquals(page.items(),r.list(owner,null,page.upper()).items());assertEquals(page.upper(),r.list(owner,null,page.upper()).upper());assertNull(r.list(UUID.randomUUID(),null,null).upper());assertThrows(RuntimeException.class,()->r.list(owner,"1",null));}
 @Test void concurrentClaimsOnlyOneExecutes()throws Exception{var db=new ModelDatabaseFixture();var r=new ComparisonRepository(db.jdbc,M);var in=input(sources());var owner=UUID.randomUUID();var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->r.claim(owner,in,now));var b=pool.submit(()->r.claim(owner,in,now));assertNotEquals(a.get(10,TimeUnit.SECONDS).execute(),b.get(10,TimeUnit.SECONDS).execute());}finally{pool.shutdownNow();}}
}
